import { _decorator, Component, Label, Node, RichText } from 'cc';
import { Eventer } from '../../../../scripts/framework/Eventer';
import { GameEventType } from '../../../gamesCommon/script/GameEventType';
import { Global } from '../../../../scripts/main/Global';
import { ScreenType } from '../../../../scripts/framework/ui/UIView';
import { UIButton } from '../../../../scripts/framework/ui/basic_ui/UIButton';
import { GameCommonModel } from '../../../gamesCommon/script/GameCommonModel';
import { RollCommonModel } from '../RollCommonModel';
import GamesData from '../../../gamesCommon/script/GamesData';
import GameResPath from '../../../gamesCommon/script/constDatas/GameResPath';
import i18n from '../../../../scripts/framework/language/i18n';
import { RollComUtils } from '../utils/RollComUtils';
import { GameComUtils } from '../../../gamesCommon/script/utils/GameComUtils';
const { ccclass, property } = _decorator;

@ccclass('RollBetViewA_2')
export class RollBetViewA_2 extends Component {

    @property(Label)
    public lab_title: Label;

    @property(UIButton)
    public dec_bet_btn: UIButton;
    @property(UIButton)
    public add_bet_btn: UIButton;
    @property(RichText)
    public lab_bet_title: RichText;
    @property(Label)
    public lab_bet: Label;

    @property(UIButton)
    public dec_value_btn: UIButton;
    @property(UIButton)
    public add_value_btn: UIButton;
    @property(Label)
    public lab_value_title: Label;
    @property(Label)
    public lab_value: Label;

    @property(UIButton)
    public dec_total_bet_btn: UIButton;
    @property(UIButton)
    public add_total_bet_btn: UIButton;
    @property(Label)
    public lab_total_title: Label;
    @property(Label)
    public lab_total_bet: Label;

    @property(UIButton)
    public max_bet_btn: UIButton;
    private clickTarget: UIButton = null
    private _otherTarget: UIButton = null
    private clickTargetAdd: UIButton = null
    private clickTargetDec: UIButton = null
    private get otherTarget() {
        return this._otherTarget = this.clickTarget == this.clickTargetAdd ? this.clickTargetDec : this.clickTargetAdd;
    }

    /**0:bet 1:value 2 total */
    private _sectionArray: number[][] = [];

    start() {
        if (GameCommonModel.getInstance().valueAGameId.indexOf(Global.gameId) != -1) {
            this._onScreenSwitch();
        }
        //this.init();
    }
    protected onEnable(): void {

    }
    private ScreenType = 1

    public init(btns, screenType): void {
        this.ScreenType = screenType
        this._sectionArray = [];

        this.node.active = false;
        this.clickTargetAdd = btns[0]
        this.clickTargetDec = btns[1]
        if (GameCommonModel.getInstance().valueAGameId.indexOf(Global.gameId) != -1) {
            this._addEvents();
            // if (!this.rollBetViewA.node.active || !this.other_btm.rollBetViewA.node.active) {
            this.node.active = true;
            this._updateBet();
            if (GameCommonModel.getInstance().valueAGameId.indexOf(Global.gameId) != -1) {
                this._onScreenSwitch();
            }
            // }
        }
    }
    updateBetView() {
        let isLand = Global.gameScreenType == ScreenType.Landscape ? true : false
        if (isLand) {
            if (this.ScreenType == 2)
                return
        } else {
            if (this.ScreenType == 1)
                return
        }
        if (!this.clickTargetDec.enabled && !this.clickTargetAdd.enabled) return
        let curBet = GameCommonModel.getInstance().curBet;
        let line = RollCommonModel.getInstance().curBetLine + RollCommonModel.getInstance().doubleLine
        let value = GameCommonModel.getInstance().curValue;
        let bet = RollCommonModel.getInstance().totalBet
        if (GameCommonModel.getInstance().valueAGameId.indexOf(Global.gameId) != -1) {
            bet = curBet * line * RollCommonModel.getInstance().betRate * value;
        }
        if (this._sectionArray.length <= 0) {
            this.intBtnState(1, false)
            this.intBtnState(0, false)
            this._updateBet()
        }
        if (this._sectionArray.length) {
            this.intBtnState(1, true)
            this.intBtnState(0, true)
            for (let i = 0; i < this._sectionArray.length; i++) {
                if (this._sectionArray[i][2] == bet) {
                    if (i == this._sectionArray.length - 1) {
                        this.intBtnState(1, false)
                    } else {
                        this.intBtnState(1, true)
                    }
                    if (i == 0)
                        this.intBtnState(0, false)
                    else {
                        this.intBtnState(0, true)
                    }
                }
            }
            this.initValueBtns()
        }
    }
    protected update(dt: number): void {
        // this.updateBetView()
    }
    /**
     * 初始化annual状态
     * @param target 目标按钮 0 dec 1 add
     * @param enable 是否开启
     */
    private intBtnState(target, enable) {
        if (target == 0) {
            if (this.clickTargetDec) {
                this.clickTargetDec.node.setScale(1, 1)
                this.clickTargetDec.enabled = enable
                this.clickTargetDec.setColor(enable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor)
            }

        } else if (target == 1) {
            if (this.clickTargetAdd) {
                this.clickTargetAdd.node.setScale(1, 1)
                this.clickTargetAdd.enabled = enable
                this.clickTargetAdd.setColor(enable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor)
            }

        }

    }

    private _addEvents() {
        this.add_value_btn.touchEndedFun = this.onBetClick.bind(this);
        this.dec_value_btn.touchEndedFun = this.onBetClick.bind(this);

        this.add_bet_btn.touchEndedFun = this.onValueClick.bind(this);
        this.dec_bet_btn.touchEndedFun = this.onValueClick.bind(this);

        this.add_total_bet_btn.touchEndedFun = this.onTotalBetClick.bind(this);
        this.dec_total_bet_btn.touchEndedFun = this.onTotalBetClick.bind(this);

        this.max_bet_btn.touchEndedFun = this.onMaxClick.bind(this);
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this._onScreenSwitch, this);
        Eventer.getInstance().on(GameEventType.RollUpdateBet, this._updateBet, this);
        Eventer.getInstance().on(GameEventType.OnReceiveSlotInfo, this.initInfo, this);
        Eventer.getInstance().on(GameEventType.RollChageBet, this.totalBetClickEven, this);

    }
    public setEnable(enable: boolean, btns: UIButton[]) {
        this.clickTargetAdd = btns[0]
        this.clickTargetDec = btns[1]
        this.add_bet_btn.enabled = enable
        this.dec_bet_btn.enabled = enable
        this.add_bet_btn.setColor(enable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor)
        this.dec_bet_btn.setColor(enable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor)
        // RollComUtils.setBuyButtonOpacity(this.add_bet_btn.node, !enable)
        // RollComUtils.setBuyButtonOpacity(this.dec_bet_btn.node, !enable)
        this.updateBetView()
    }
    public totalBetClickEven(msg) {
        this.clickTarget = msg[2]
        if (GameCommonModel.getInstance().valueAGameId.indexOf(Global.gameId) == -1) return
        Eventer.getInstance().emit(GameEventType.RollCloseAutoPlayMenu);
        if (msg[0]) {
            this.onTotalBetClick(this.add_total_bet_btn, msg[1]);
        } else {
            this.onTotalBetClick(this.dec_total_bet_btn, msg[1]);
        }
        this._updateBet()
        this.updateBetView()

    }


    private initInfo() {

    }

    private onBetClick(target: UIButton) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.betList || gameComModel.betList.length <= 0) {
            return;
        }
        GameResPath.playRollCommonSound("click_1");

        let curBetIndex = GameCommonModel.getInstance().curBetIndex;
        let nextIndex: number;
        if (target == this.add_value_btn) {
            nextIndex = curBetIndex + 1;
        }
        else if (target == this.dec_value_btn) {
            nextIndex = curBetIndex - 1;
        }
        this.setBetIndex(nextIndex);
        Eventer.getInstance().emit(GameEventType.RollUpdateBet);
        Eventer.getInstance().emit(GameEventType.RollCloseAutoPlayMenu);

    }


    private setTionArr(): void {
        let gameComModel = GameCommonModel.getInstance();
        let rollCommonModel = RollCommonModel.getInstance();
        if (gameComModel.betList && gameComModel.betList.length) {
            this._sectionArray = [];
            let line = rollCommonModel.curBetLine + rollCommonModel.doubleLine
            let rate = rollCommonModel.betRate;
            for (let i = 0; i < gameComModel.betList.length; i++) {
                let bet = gameComModel.betList[i];
                for (let j = 0; j < gameComModel.valueList.length; j++) {
                    let arr = [];
                    let valueIndex = gameComModel.valueList[j];
                    let totalNum = bet * valueIndex * line * rate;
                    arr.push(i, j, totalNum);
                    this._sectionArray.push(arr);
                }
            }

            for (let i = 0; i < this._sectionArray.length - 1; i++) {
                for (let j = i; j < this._sectionArray.length - 1; j++) {
                    if (this._sectionArray[i][2] > this._sectionArray[j][2]) {
                        let temp = this._sectionArray[i];
                        this._sectionArray[i] = this._sectionArray[j];
                        this._sectionArray[j] = temp;
                    }
                }
            }
            this.updateBetView()
        }
    }

    private initLab() {
        let line = RollCommonModel.getInstance().curBetLine;
        this.lab_title.node.setPosition(-143.58, 0.12)
        this.lab_title.string = i18n.tr(1005001, [line]);
        this.lab_bet_title.string = "<b><outline color=#333333 width = 1 ><color=#A6E740>" + "COUNT" + " < /color>< /outline></b >";
        this.lab_value_title.string = i18n.tr(1005003);
        this.lab_total_title.string = i18n.tr(1005004);
    }


    private onTotalBetClick(target: UIButton, totalBetNum) {
        if (this._sectionArray.length) {
            let value = GameCommonModel.getInstance().curValue;
            let bet = GameCommonModel.getInstance().curBet;
            let line = RollCommonModel.getInstance().curBetLine;
            let rate = RollCommonModel.getInstance().betRate;
            let totalBet = value * bet * line * rate;
            if (totalBetNum) {
                totalBet = totalBetNum;
            }

            if (target == this.add_total_bet_btn) {
                let isChange = false;
                for (let i = 0; i < this._sectionArray.length; i++) {
                    if (this._sectionArray[i][2] > totalBet) {
                        this.setBetIndex(this._sectionArray[i][0], false);
                        this.setValueIndex(this._sectionArray[i][1], false);
                        this._updateValue()
                        this.updateBtnState(true)
                        if (i == this._sectionArray.length - 1) {
                            this.updateBtnState(false)
                        }
                        isChange = true;
                        break;
                    }
                }
                if (!isChange) {
                    this.updateBtnState(false)
                }
            } else if (target == this.dec_total_bet_btn) {
                let isChange = false;
                for (let i = this._sectionArray.length - 1; i >= 0; i--) {
                    if (this._sectionArray[i][2] < totalBet) {
                        this.setBetIndex(this._sectionArray[i][0], false);
                        this.setValueIndex(this._sectionArray[i][1], false);
                        this._updateValue()
                        this.updateBtnState(true)
                        if (i == 0) {
                            this.updateBtnState(false)
                        }
                        isChange = true;
                        break;
                    }
                }
                if (!isChange) {
                    this.updateBtnState(false)
                }
            }
        }

    }
    private updateBtnState(enable) {
        if (this.clickTarget) {
            this.clickTarget.node.setScale(1, 1)
            this.clickTarget.enabled = enable
            this.clickTarget.setColor(enable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor)
        }
        if (this.otherTarget) {
            if (this.otherTarget.enabled == false) {
                this.otherTarget.enabled = true
                this.otherTarget.setColor(GameComUtils.btnEffColor)
            }

        }
    }



    private onValueClick(target: UIButton) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.valueList || gameComModel.valueList.length <= 0) {
            return;
        }
        let curValue = gameComModel.curValueIndex;
        let nextIndex: number;
        if (target == this.add_bet_btn) {
            nextIndex = curValue + 1;
        }
        else if (target == this.dec_bet_btn) {
            nextIndex = curValue - 1;
        }
        this.setValueIndex(nextIndex);
        GameResPath.playRollCommonSound("click_1");
        Eventer.getInstance().emit(GameEventType.RollUpdateBet);
        Eventer.getInstance().emit(GameEventType.RollCloseAutoPlayMenu);
    }

    /**
    * 设置押注索引
    * @param betIndex 索引
    */
    public setBetIndex(betIndex: number, updateEnable = true) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.betList || gameComModel.betList.length <= 0) {
            return;
        }
        let betCount = gameComModel.betList.length;
        if (betIndex < 0) {
            betIndex = betCount - 1;
        }
        if (betIndex >= betCount) {
            betIndex = 0;
        }
        gameComModel.curBetIndex = betIndex;
        if (updateEnable) this._updateValue();
    }

    /**
   * 设置押注索引
   * @param valueIndex 索引
   */
    public setValueIndex(valueIndex: number, updateEnable = true) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.valueList || gameComModel.valueList.length <= 0) {
            return;
        }

        // Log.e("valueIndex==", valueIndex);
        let betCount = gameComModel.valueList.length;
        if (valueIndex <= 0) {
            this.updateValueBtns(0, false)
        } else if (valueIndex >= betCount - 1) {
            this.updateValueBtns(1, false)
        } else {
            this.updateValueBtns(3, true)
        }
        if (valueIndex < 0) {
            return
            valueIndex = betCount - 1;
        }
        if (valueIndex >= betCount) {
            return
            valueIndex = 0;
        }
        gameComModel.curValueIndex = valueIndex;
        if (updateEnable) this._updateValue();
    }
    updateValueBetView() {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.valueList || gameComModel.valueList.length <= 0) {
            return;
        }
        let valueIndex = gameComModel.curValueIndex
        let betCount = gameComModel.valueList.length;
        this.updateValueBtns(3, true)
        if (valueIndex <= 0) {
            this.updateValueBtns(0, false)
        } else if (valueIndex >= betCount - 1) {
            this.updateValueBtns(1, false)
        }
    }
    initValueBtns() {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.valueList || gameComModel.valueList.length <= 0) {
            return;
        }
        let betCount = gameComModel.valueList.length;
        let valueIndex = gameComModel.curValueIndex;
        if (valueIndex <= 0) {
            this.updateValueBtns(0, false)
        } else if (valueIndex >= betCount - 1) {
            this.updateValueBtns(1, false)
        } else {
            this.updateValueBtns(3, true)
        }
    }
    /**
     * 
     * @param target 0 减 1 加 3两个
     * @param enable 
     */
    private updateValueBtns(target, enable) {
        if (target == 3) {
            this.setValueDec(enable)
            this.setValueAdd(enable)
        }
        if (target == 0) {
            this.setValueDec(enable)
        }
        if (target == 1) {
            this.setValueAdd(enable)
        }
    }
    setValueDec(enable) {
        this.dec_bet_btn.node.setScale(1, 1)
        this.dec_bet_btn.enabled = enable
        this.dec_bet_btn.setColor(enable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor)
    }
    setValueAdd(enable) {
        this.add_bet_btn.node.setScale(1, 1)
        this.add_bet_btn.enabled = enable
        this.add_bet_btn.setColor(enable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor)
    }

    private _updateBet() {
        let value = GameCommonModel.getInstance().curValue;
        let bet = GameCommonModel.getInstance().curBet;
        let line = RollCommonModel.getInstance().curBetLine + RollCommonModel.getInstance().doubleLine
        let rate = RollCommonModel.getInstance().betRate;
        let total = value * bet * line * rate;
        this.lab_bet.string = value.toString();
        this.lab_value.string = Global.currencyName + GamesData.formatScore(bet, false);;
        this.lab_total_bet.string = Global.currencyName + GamesData.formatScore(total, false);
        this.setTionArr();
        this.initLab();
        this.updateBetView()
    }

    private _updateValue() {
        this._updateBet();
        Eventer.getInstance().emit(GameEventType.RollUiewpdateBetView);
    }



    private onMaxClick() {
        if (this._sectionArray.length) {
            let len = this._sectionArray.length - 1;
            this.setBetIndex(this._sectionArray[len][0]);
            this.setValueIndex(this._sectionArray[len][1]);
        }

    }

    private _onScreenSwitch() {
        if (GameCommonModel.getInstance().valueAGameId.indexOf(Global.gameId) != -1) {
            this.updateValueBetView()
            this._updateBet();
        }
    }

    public offEvent() {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        Eventer.getInstance().offName(GameEventType.RollUpdateBet, this);
        Eventer.getInstance().offName(GameEventType.OnReceiveSlotInfo, this);
        Eventer.getInstance().offName(GameEventType.RollChageBet, this);
    }

    onDisable() {
        // Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        // Eventer.getInstance().offName(GameEventType.RollUpdateBet, this);
        // Eventer.getInstance().offName(GameEventType.OnReceiveSlotInfo, this);

    }

}


