import { _decorator, Component, Node, math, UITransform, Label, HorizontalTextAlignment, Vec3, SpriteFrame, Sprite, ButtonComponent, ccenum, CCInteger, VerticalTextAlignment, RichText } from 'cc';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
import { Global } from '../../../../../scripts/main/Global';
import { ScreenType } from '../../../../../scripts/framework/ui/UIView';
;
const { ccclass, property, executionOrder } = _decorator;

export enum HorizontalAlignmen {
    __enums__ = null,
    LEFT = 0,
    CENTER = 1,
    RIGHT = 2,
    NONE
}

export enum VerticalAlignmen {
    __enums__ = null,
    TOP = 0,
    CENTER = 1,
    BOTTOM = 2,
    NONE
}

/**
 * UILabel横竖屏设置组件
 */
@ccclass('UILabelScreenSwitch')
@executionOrder(-1)
export class UILabelScreenSwitch extends Component {


    @property({ type: HorizontalAlignmen, displayName: "横屏水平对齐", serializable: true, tooltip: "" })
    public hor_hAlign: HorizontalAlignmen = HorizontalAlignmen.NONE;
    @property({ type: HorizontalAlignmen, displayName: "竖屏水平对齐", serializable: true, tooltip: "" })
    public ver_hAlign: HorizontalAlignmen = HorizontalAlignmen.NONE;

    @property({ type: VerticalAlignmen, displayName: "横屏垂直对齐", serializable: true, tooltip: "" })
    public hor_vAlign: VerticalAlignmen = VerticalAlignmen.NONE;
    @property({ type: VerticalAlignmen, displayName: "竖屏垂直对齐", serializable: true, tooltip: "" })
    public ver_vAlign: VerticalAlignmen = VerticalAlignmen.NONE;

    @property({ type: CCInteger, displayName: "横屏字体大小", serializable: true, tooltip: "" })
    public hor_size: number = -1;
    @property({ type: CCInteger, displayName: "竖屏字体大小", serializable: true, tooltip: "" })
    public ver_size: number = -1;


    start() {
        this.addListener();
        this.onScreenSwitch();
    }

    public onDestroy() {
        this.removeListener();
    }

    private onScreenSwitch(): void {
        let label: any = this.node.getComponent(Label)
        if (!label) label = this.node.getComponent(RichText)
        if (label) {
            if (Global.gameScreenType == ScreenType.Landscape) {
                if (this.hor_hAlign != HorizontalAlignmen.NONE) {
                    label.horizontalAlign = HorizontalTextAlignment[HorizontalAlignmen[this.hor_hAlign]];

                    if (label.horizontalAlign == HorizontalTextAlignment.CENTER) {
                        this.node.getComponent(UITransform).anchorX = 0.5
                    } else if (label.horizontalAlign == HorizontalTextAlignment.LEFT) {
                        this.node.getComponent(UITransform).anchorX = 0
                    } else if (label.horizontalAlign == HorizontalTextAlignment.RIGHT) {
                        this.node.getComponent(UITransform).anchorX = 1
                    }

                }
                if (this.hor_vAlign != VerticalAlignmen.NONE) {
                    label.verticalAlign = VerticalTextAlignment[VerticalAlignmen[this.hor_hAlign]];
                }
                if (this.hor_size > 0) {
                    label.fontSize = this.hor_size;
                }

            } else {
                if (this.ver_hAlign != HorizontalAlignmen.NONE) {
                    label.horizontalAlign = HorizontalTextAlignment[HorizontalAlignmen[this.ver_hAlign]];
                    if (label.horizontalAlign == HorizontalTextAlignment.CENTER) {
                        this.node.getComponent(UITransform).anchorX = 0.5
                    } else if (label.horizontalAlign == HorizontalTextAlignment.LEFT) {
                        this.node.getComponent(UITransform).anchorX = 0
                    } else if (label.horizontalAlign == HorizontalTextAlignment.RIGHT) {
                        this.node.getComponent(UITransform).anchorX = 1
                    }
                }
                if (this.ver_vAlign != VerticalAlignmen.NONE) {
                    label.verticalAlign = VerticalTextAlignment[VerticalAlignmen[this.ver_vAlign]];
                }
                if (this.ver_size > 0) {
                    label.fontSize = this.ver_size;
                }
                this.node.getComponent(UITransform).anchorX = 0
            }
        }
    }

    private addListener(): void {
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    private removeListener(): void {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }
}

