import { _decorator, Component, HorizontalTextAlignment, Label, Layers, Node, NodeEventType, Sprite, SpriteFrame, UITransform, VerticalTextAlignment } from 'cc';
import { RollCommonManager } from '../RollCommonManager';
import { ResManager } from '../../../../scripts/framework/manager/ResManager';
import { BUNDLE_NAME } from '../../../gamesCommon/script/UIGameDefined';
import { RollCommonModel } from '../RollCommonModel';
const { ccclass, property } = _decorator;

@ccclass('RollAutoPlay')
export class RollAutoPlay extends Component {

    /** 按钮背景父节点 */
    private _layBg: Node;
    /** 按钮文本父节点 */
    private _layLab: Node;

    /** 初始x坐标 */
    private _startx: number = -170;
    /** 初始x坐标 */
    private _starty: number = 32;
    /** 间隔x坐标 */
    private _spacex: number = 114;
    /** 间隔y坐标 */
    private _spacey: number = -64;
    /** 文本一排个数 */
    private _rowNum: number = 4;

    /** 节点名 */
    private _nodeName: string = 'bg_node_';

    /** 按钮背景列表 */
    private _btnBgList: Node[] = [];
    /** 按钮文本列表 */
    private _btnLabList: Node[] = [];

    start() {
        this._layBg = this.node.getChildByName('lay_bg');
        this._layLab = this.node.getChildByName('lay_lab');
        this.initBtns();
        this.refreshBtns();
    }

    update(deltaTime: number) {

    }

    private initBtns() {
        let list = RollCommonModel.getInstance().autoPlayTimesList;
        for (let key in list) {
            let idx = Number(key);
            let num = list[key]; //次数

            let labx = this._startx + idx % this._rowNum * this._spacex;
            let laby = this._starty + Math.floor(idx / this._rowNum) * this._spacey;
            let labNode = new Node();
            labNode.layer = Layers.Enum.UI_2D;
            labNode.setPosition(labx, laby);
            let lab = labNode.addComponent(Label);
            lab.string = num.toString();
            lab.fontSize = 26;
            lab.horizontalAlign = HorizontalTextAlignment.CENTER;
            lab.verticalAlign = VerticalTextAlignment.CENTER;
            this._layLab.addChild(labNode);
            this._btnLabList.push(this._layLab);

            let path = 'resources/texture/gameBottom/hengban/btn_autoplay01/spriteFrame';
            let bgNode = new Node();
            bgNode.layer = Layers.Enum.UI_2D;
            bgNode.setScale(0.85, 0.85);
            bgNode.addComponent(Sprite);
            bgNode.on(NodeEventType.TOUCH_END, this.onBtnTouch, this);
            bgNode.name = `${this._nodeName}${idx}`;
            ResManager.Instance().load(BUNDLE_NAME.gamesCommon, path, SpriteFrame, () => { }, (evt: any) => {
                let spriteFrame: SpriteFrame = evt.data;
                bgNode.getComponent(Sprite).spriteFrame = spriteFrame;
            });
            this._layBg.addChild(bgNode);
            this._btnBgList.push(bgNode);
        }
    }

    /**
     * 刷新按钮状态
     */
    private refreshBtns() {
        for (let key in this._btnBgList) {
            let node = this._btnBgList[key];
            let name = node.name;
            let idx = Number(name.split(this._nodeName)[1]);
            let resName = RollCommonModel.getInstance().selAutoPlayIdx == idx ? 'btn_autoplay00' : 'btn_autoplay01';
            let path = `resources/texture/gameBottom/hengban/${resName}/spriteFrame`
            ResManager.Instance().load(BUNDLE_NAME.gamesCommon, path, SpriteFrame, () => { }, (evt: any) => {
                let spriteFrame: SpriteFrame = evt.data;
                node.getComponent(Sprite).spriteFrame = spriteFrame;
            });
        }
    }

    /**
     * 按钮点击
     * @param event
     */
    private onBtnTouch(event) {
        let node: Node = event.target;
        let name = node.name;
        let idx = Number(name.split(this._nodeName)[1]);
        let selIdx = RollCommonModel.getInstance().selAutoPlayIdx;
        if (selIdx == idx) {
            RollCommonModel.getInstance().selAutoPlayIdx = -1;
        } else {
            RollCommonModel.getInstance().selAutoPlayIdx = idx;
        }
        this.refreshBtns();
    }
}

