import { Component, Sprite, SpriteFrame, Node, UITransform } from "cc";
import { RollBottomWinLineVo } from "../RollBottom";

export class RollBottomWinLineBaseComp extends Component {

    /** 最大宽 */
    private _maxWidth: number = 600;

    public setData(data: RollBottomWinLineVo) {
    }

    /**
     * 设置精灵帧
     * @param node 
     * @param res 
     */
    protected setSpriteFrame(node: Node, res: SpriteFrame) {
        node.getComponent(Sprite).spriteFrame = res;
        node.getComponent(UITransform).setContentSize(30, 30);
        node.active = true;
    }

    update() {
        if (this.width > this._maxWidth) {
            let scale = this._maxWidth / this.width;
            this.node.setScale(scale, scale);
        }
    }

    get width(): number {
        return this.node.getComponent(UITransform).width
    }
}