import { RollCommonModel } from './../../RollCommonModel';
import { _decorator, Component, Node, RichText } from 'cc';
import { GameCommonModel } from '../../../../gamesCommon/script/GameCommonModel';
import { betListBtn } from './betListBtn';
import { betListBoard } from './betListBoard';
import { Global } from '../../../../../scripts/main/Global';
import GamesData from '../../../../gamesCommon/script/GamesData';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
import i18n from '../../../../../scripts/framework/language/i18n';
import { RollBottom } from '../RollBottom';
import { UIButton } from '../../../../../scripts/framework/ui/basic_ui/UIButton';
const { ccclass, property } = _decorator;

@ccclass('RollbetViewA')
export class RollbetViewA extends Component {
    /**btn按钮组*/
    private betBtnList: betListBtn[] = [];
    private betListBG: Node = null
    @property(Node)
    private betShowBtn: Node = null
    @property(betListBoard)
    private bet_ListBord: betListBoard;
    @property(RichText)
    public lab_bet: RichText;
    private ScreenType = 1
    private _betListInfo: number[] = []
    /**另一个横屏或竖屏节点 */
    @property(Node)
    public other_btmNode: Node;
    public _other_btm: RollBottom;
    private get other_btm(): RollBottom {
        if (this._other_btm) {
            return this._other_btm
        }
        this.initRollBetA(this.ScreenType)
        return this._other_btm;
    };
    private showBetBoardGames: number[] = [3000218]
    private isShowRollBetA() {
        return this.showBetBoardGames.includes(Global.gameId)
    }
    public initRollBetA(screenType) {
        if (this.isShowRollBetA()) {
            let gameComModel: GameCommonModel = GameCommonModel.getInstance();
            if (gameComModel.betList) {
                this._betListInfo = gameComModel.betList
                this.node.active = true
                this.betShowBtn.active = true
                this._other_btm = this.other_btmNode.getChildByName("BottomPref").getComponent(RollBottom);
                this.ScreenType = screenType
                this.betBtnList = this.bet_ListBord.initBetLIst(GameCommonModel.getInstance().betList, this.ScreenType)
                this.addEventBetBtns(this.betBtnList)
                this.initBetShowBtn();
                this.setBetIndex(gameComModel.curBetIndex, true);
            }
        } else {
            this.betShowBtn.active = false
        }
    }
    public setBetBtnCheck(index: number) {
        if (this.betBtnList && this.betBtnList.length > 0) {
            this.betBtnList[GameCommonModel.getInstance().curBetIndex].setCheckBtn(false)
            this.betBtnList[index].setCheckBtn(false)
        }
    }
    public setBetBtnCancel(index: number) {
        if (this.betBtnList && this.betBtnList.length > 0) {
            this.betBtnList[GameCommonModel.getInstance().curBetIndex].setCheckBtn(false)
        }
    }
    private initBetShowBtn() {
        this.betShowBtn.active = true
        this.betListBG = this.bet_ListBord.boardBG
        this.updateTriangle()
        this.betShowBtn.getComponent(UIButton).touchEndedFun = this.updateBetBoard.bind(this)
        this.betListBG.on(Node.EventType.TOUCH_END, this.updateBetBoard, this);
    }
    private canClick = false
    public setCanClckState(enable) {
        this.canClick = enable
    }
    private updateBetBoard() {
        if (!this.canClick) return
        let enable = !this.bet_ListBord.node.active
        this.bet_ListBord.node.active = enable
        this.betListBG.active = enable
        this.updateTriangle()
        this.updateBetList()
    }
    updateTriangle() {
        let enable = !this.bet_ListBord.node.active
        let land = this.ScreenType == 1
        let btn_triangle = this.betShowBtn.getChildByName("btn_triangle")
        let ang1 = land ? 180 : 0
        let ang2 = land ? 0 : 180
        btn_triangle.angle = enable ? ang1 : ang2
    }
    private addEventBetBtns(betBtnList: betListBtn[]) {
        if (!betBtnList || betBtnList.length <= 0) return;
        for (let i = 0; i < betBtnList.length; i++) {
            betBtnList[i].node.getComponent(UIButton).touchBeganFun = this.setCheck.bind(this, betBtnList[i].index)
            betBtnList[i].node.getComponent(UIButton).touchCancelFun = this.setCancel.bind(this, betBtnList[i].index)
            betBtnList[i].node.getComponent(UIButton).touchEndedFun = this.setBetIndex.bind(this, betBtnList[i].index, false)
        }
    }
    private updateBetList() {
        if (!this.betBtnList || this.betBtnList.length <= 0) return;
        for (let i = 0; i < this.betBtnList.length; i++) {
            this.betBtnList[i].updateBet(this._betListInfo[i])
        }
    }

    private setCheck(index) {
        this.betBtnList[index].setCheckBtn(true)
    }
    private setCancel(index) {
        this.betBtnList[index].setCheckBtn(false)
    }
    /**
     * 设置押注索引
     * @param betIndex 索引
     */
    public setBetIndex(betIndex: number, init = false) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.betList || gameComModel.betList.length <= 0) {
            return;
        }
        let betCount = gameComModel.betList.length;
        if (betIndex < 0) {
            betIndex = betCount - 1;
        }
        if (betIndex >= betCount) {
            betIndex = 0;
        }
        this.setBetBtnCheck(betIndex)
        gameComModel.curBetIndex = betIndex;
        this.updateBet();
        if (!init)
            this.updateBetBoard()
    }

    public updateBet() {
        let value = GameCommonModel.getInstance().curValue;
        let bet = RollCommonModel.getInstance().totalBet
        if (GameCommonModel.getInstance().valueGameId.indexOf(Global.gameId) != -1) {
            bet = RollCommonModel.getInstance().totalBet * value;
        }
        let score = GamesData.formatScore(bet, false);
        this.lab_bet.string = this.betStr(score);
        if (this.other_btm)
            this.other_btm.lab_bet.string = this.betStr(score);
        Eventer.getInstance().emit(GameEventType.RollUpdateBet, bet);
        Eventer.getInstance().emit(GameEventType.RollChageBet);
        Eventer.getInstance().emit(GameEventType.RollCloseAutoPlayMenu);
    }
    private betStr(score: number | string): string {
        return i18n.tr(3002010, `${Global.currencyName}${score}`);
    }

    start() {

    }
    update(deltaTime: number) {

    }
}


