import { _decorator, Component, Node, math, UITransform, Label, HorizontalTextAlignment, Vec3 } from 'cc';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
import { Global } from '../../../../../scripts/main/Global';
import { ScreenType } from '../../../../../scripts/framework/ui/UIView';
;
const { ccclass, property } = _decorator;

/**
 * 通用底板横竖屏设置组件
 */
@ccclass('NodeScreenSwitch')
export class NodeScreenSwitch extends Component {

    @property({ type: Node, tooltip: "横屏的节点位置" })
    private horNode: Node;
    @property({ type: Node, tooltip: "竖屏的节点位置" })
    private verNode: Node;

    @property({ type: [Node], tooltip: "只横屏显示的节点" })
    private horList: Node[] = [];
    @property({ type: [Node], tooltip: "只竖屏显示的节点" })
    private verList: Node[] = [];

    start() {
        this.addListener();
        this.onScreenSwitch();
    }

    public onDestroy() {
        this.removeListener();
    }

    private onScreenSwitch(): void {
        this.horNode.active = Global.gameScreenType == ScreenType.Landscape
        this.verNode.active = Global.gameScreenType != ScreenType.Landscape
        let posNode = Global.gameScreenType == ScreenType.Landscape ? this.horNode : this.verNode

        posNode.children.forEach(element => {
            this.updateNodePos(element, this.node)
        });

        this.horList.forEach(element => {
            element.active = Global.gameScreenType == ScreenType.Landscape
        });
        this.verList.forEach(element => {
            element.active = Global.gameScreenType != ScreenType.Landscape
        });
    }

    private updateNodePos(node: Node, updateParent: Node) {
        let updateNode = updateParent.getChildByName(node.name)
        if (updateNode) {
            updateNode.setWorldPosition(new Vec3(node.worldPosition))
            node.children.forEach(element => {
                this.updateNodePos(element, updateNode)
            });
        }
    }

    private addListener(): void {
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    private removeListener(): void {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }
}

