import { _decorator } from 'cc';
import { Eventer } from '../../../scripts/framework/Eventer';
import { EntryManager } from '../../../scripts/framework/hall/entry/EntryManager';
import { Singleton } from '../../../scripts/framework/Singleton';
import { Global } from '../../../scripts/main/Global';
import { GameCommonManager } from '../../gamesCommon/script/GameCommonManager';
import { GameCommonModel, LoginVo_s2c } from '../../gamesCommon/script/GameCommonModel';
import { GameEventType } from '../../gamesCommon/script/GameEventType';
import GamesData from '../../gamesCommon/script/GamesData';
import { GameProtocolId } from '../../gamesCommon/script/gameSocket/GameProtocolId';
import GameSocketManager, { C2S_ProtocolParams, S2C_ProtocolParams } from '../../gamesCommon/script/gameSocket/GameSocketManager';
import { ShakeTool } from './media/ShakeTool';
import { GetBonusVo_s2c, GetMajMinVo_s2c, PayOutBonusVo_s2c, RollCommonModel } from './RollCommonModel';
import { HttpReqPack } from '../../../scripts/common/net/http/HttpReqPack';
import { HttpMethod } from '../../../scripts/common/define/EnumDefine';
import { HttpMgr } from '../../../scripts/common/net/http/HttpMgr';
import { HttpRespPack } from '../../../scripts/common/net/http/HttpRespPack';
import GameHttpData from '../../gamesCommon/script/GameHttpData';
import { UIManager } from '../../../scripts/framework/ui/UIManager';
import { UIID_GAME } from '../../gamesCommon/script/UIGameDefined';
import WebMsgHandler from '../../../scripts/common/net/http/WebMsgHandler';
import { HTTP_CONTENT_TYPE } from '../../../scripts/common/net/http/NetHttp';
const { ccclass, property } = _decorator;

@ccclass('RollCommonManager')
export class RollCommonManager extends Singleton<RollCommonManager>() {

    private _model: RollCommonModel;

    constructor() {
        super();
        this.init();
    }

    private init() {
        this._model = RollCommonModel.getInstance();
    }

    /**
     * registerMsgListener
     */
    public registerMsgListener() {
        GameSocketManager.getInstance().registerMsgListener<S2C_ProtocolParams<LoginVo_s2c>>(GameProtocolId.LOGIN, this._s2cLogin, this);
        GameSocketManager.getInstance().registerMsgListener<S2C_ProtocolParams<GetMajMinVo_s2c>>(GameProtocolId.GETMAJMIN, this._s2cGetMajMin, this);
        GameSocketManager.getInstance().registerMsgListener<S2C_ProtocolParams<GetBonusVo_s2c>>(GameProtocolId.GETBONUS, this._s2cGetBonus, this);
        GameSocketManager.getInstance().registerMsgListener<S2C_ProtocolParams>(GameProtocolId.SLOTINFO, this._s2cSlotInfo, this);
        GameSocketManager.getInstance().registerMsgListener<S2C_ProtocolParams>(GameProtocolId.PAYOUTBONUS, this._s2cPayOutBonus, this);
        GameSocketManager.getInstance().registerMsgListener<S2C_ProtocolParams>(GameProtocolId.SLOTCOST, this._s2cSlotCost, this);

        Eventer.getInstance().on(GameEventType.SocketOpen, this.socketOpenCallBack);
        Eventer.getInstance().on(GameEventType.GameReLogin, this.reLogin, this);
        Eventer.getInstance().on(GameEventType.OnReceiveBet, this.receiveBet, this);
    }

    private socketOpenCallBack(evt): void {
        GameCommonManager.getInstance().login(Global.gameId);
    }
    /**
    * 请求后台免费游戏显示信息
    */
    public c2sEntranceInfo(gameId: number): void {
        let str: string = `entranceInfo?gameId=${gameId}`;
        let pack: HttpReqPack = HttpReqPack.create(GameHttpData.gameApi, str, HttpMethod.GET);
        HttpMgr.Instance().send(pack, null, this.php2cEntranceInfo.bind(this), null, HTTP_CONTENT_TYPE.TEXTPLAIN);

    }
    /** 后台免费游戏显示信息 */
    private php2cEntranceInfo(param: HttpRespPack): void {
        let data: HttpRespPack = param;
        if (data && data.code == 200) {
            this._model.isShowSpecBuy = data.data.isFreeShow;
            Eventer.getInstance().emit(GameEventType.isFreeShow, data);
        }
    }
    /**
    * 接收登录
    * @param data {"message":{"issucc":number,"uid":number,"utype":number},"succ":true,"errinfo":"ok","type":"login"}
    */
    private _s2cLogin(data: S2C_ProtocolParams<LoginVo_s2c>) {
        if (!data || !data.message || data.message.issucc != 1) {
            Log.w("login fail");
            return;
        }

        if (data.succ == false) {
            return;
        }
        if (data.message.issucc) {
            GameCommonModel.getInstance().userType = data.message.utype;
            GamesData.userId = data.message.uid;
            Global.account = data.message.account;
            Global.currency = WebMsgHandler.webSrc.serverDebug ? WebMsgHandler.webSrc.moneyType : data.message.currency;
            Global.quickSpin = false;
        }

        GameCommonManager.getInstance().c2sUserInfo();
        // 暂时不取获取排行榜数据，服务器报错
        // GameCommonManager.getInstance().c2sActRewardInfo();
        this.c2sSlotInfo();
        Eventer.getInstance().emit(GameEventType.OnLoginSuccess, data);
    }

    /**
     * 获取彩金最大最小值
     */
    public c2sGetMajMin() {
        let msgObj = {
            type: GameProtocolId.GETMAJMIN,
            message: {}
        }

        GameSocketManager.getInstance().sendMessage<C2S_ProtocolParams>(GameProtocolId.GETMAJMIN, msgObj);
    }

    /**
     * 获取彩金最大最小值
     * @param data {"message":{"major":number[],"minor":number[]},"succ":true,"errinfo":"ok","type":"getmajmin"}
     */
    private _s2cGetMajMin(data: S2C_ProtocolParams<GetMajMinVo_s2c>) {
        Eventer.getInstance().emit(GameEventType.OnGetJackPotMaxMin, data.message);
    }

    /**
    * 获取彩金值
    * @param type 彩金类型
    */
    public c2sGetBonus(type: string) {
        let msgObj = {
            type: GameProtocolId.GETBONUS,
            message: {
                bonustype: type
            }
        }
        GameSocketManager.getInstance().sendMessage<C2S_ProtocolParams>(GameProtocolId.GETBONUS, msgObj);
    }

    /**
     * 获取彩金值
     * @param data {"message":{"bonustype":string,"bonus":number},"succ":true,"errinfo":"ok","type":"getbonus"}
     */
    private _s2cGetBonus(data: S2C_ProtocolParams<GetBonusVo_s2c>) {
        Eventer.getInstance().emit(GameEventType.OnGetBonus, data.message);
    }
    /**
    * 请求押注信息
    */
    public c2sSlotInfo() {
        let msgObj = {
            type: GameProtocolId.SLOTINFO,
            message: {}
        }
        GameSocketManager.getInstance().sendMessage<C2S_ProtocolParams>(GameProtocolId.SLOTINFO, msgObj);
    }

    /**
     * 押注信息返回
     * @param data {"message":{"min":number,"max":number,"coinrate":number,"ratelist":number[],"betList":number[],"defaultBetValue":number,"extraBetList":number[],"defaultExtraBetValue":number,"coin":number[],"userlevel":number,"userlevelPower":number,"level":number[],"value":number[],"jp":number},"succ":true,"errinfo":"ok","type":"slotinfo"}
     */
    private _s2cSlotInfo(data: S2C_ProtocolParams) {
        console.log("_s2cSlotInfo data.message.betList",JSON.stringify(data.message.betList));
        console.log("_s2cSlotInfo data.message.bet",JSON.stringify(data.message.bet));
        GameCommonModel.getInstance().receiveSlotInfo = true;
        GameCommonModel.getInstance().coinRate = data.message.coin_rate;
        
        GameCommonModel.getInstance().betList = data.message.bet;
        GameCommonModel.getInstance().defaultBet = 20000;
        // GameCommonModel.getInstance().defaultBet = data.message.default_bet;
        GameCommonModel.getInstance().maxLimit = data.message.max_limit;
        GameCommonModel.getInstance().updateBetList(data.message.max, data.message.min);
        if (GameCommonModel.getInstance().curBetIndex == -1) //没设置过 才用默认值
            GameCommonModel.getInstance().curBetIndex = GameCommonModel.getInstance().defaultBetIndex;
        Eventer.getInstance().emit(GameEventType.OnReceiveSlotInfo, data.message);
    }


    /**
     * 中彩金
     * @param data {"message":{"bonustype":string,"bonus":number},"succ":true,"errinfo":"ok","type":"slotbet113"}
     */
    private _s2cPayOutBonus(data: S2C_ProtocolParams<PayOutBonusVo_s2c>) {
        let message = data.message;
        if (GamesData.userId == message.uid) {
            this._model.jackPotData = message;
            Log.d("中彩金=>", message);
        }
    }
    /**
     * @description: 当前牌面的消耗
     * @param {S2C_ProtocolParams} data
     * @return {*}
     */
    private _s2cSlotCost(data: S2C_ProtocolParams) {
        GameCommonModel.getInstance().slotCost = data.message.cost;
        Log.d("消耗=>", data);
    }

    /**
     * 加载回放
     */
    loadPlayback() {
        if (!Global.playback)
            return;
        console.log('Start Loading Playback');
        RollCommonManager.getInstance().c2javaPlaybackInfo(Global.playbackId);
    }

    /**
     * 获取游戏记录数据
     */
    public c2javaPlaybackInfo(code: string): void {
        let str: string = JSON.stringify({ code: code, gameId: Global.gameId });
        let pack: HttpReqPack = HttpReqPack.create(GameHttpData.gameApi + 'history/detail', str, HttpMethod.POST);
        HttpMgr.Instance().send(pack, null, this.java2cPlayback.bind(this));
    }

    public java2cPlayback(httpResp: HttpRespPack) {
        if (httpResp.code != 200)
            console.error('Playback get record fail!');
        Global.playbackVo = httpResp.data;
        Eventer.getInstance().emit(GameEventType.OnReceivePlayback);
    }

    /** 打开游戏帮助界面 */
    public showHelp() {
        let bet = RollCommonModel.getInstance().totalCurBet;
        let money = GamesData.serverToMoney(bet);
        money = GamesData.exact(money);
        let point = GamesData.point;
        let value = GamesData.formatValue(money, point, false, true);

        UIManager.getInstance().open(UIID_GAME.UIGameHelp, value);
    }

    private receiveBet() {
        this._model.checkCstStopState();
    }

    /**
     * clean
     */
    public clean() {
        Eventer.getInstance().offName(GameEventType.GameReLogin, this);
        ShakeTool.instance.clean();
        this._model.clean();
        this._model = null;

        RollCommonModel.clearInstance();
    }

    private reLogin() {
        RollCommonModel.getInstance().verRollFunView = null;
        RollCommonModel.getInstance().horRollFunView = null;
        ShakeTool.instance.clean();
        this._model.reLogin();
        UIManager.getInstance().closeAll();
        GameCommonManager.getInstance().reLogin();
        RollCommonManager.getInstance().c2sEntranceInfo(GamesData.gameId);
        // EntryManager.getInstance().enterBundle(Global.gameId + "");
    }
}

