import { EventTarget, __private } from "cc";

/**
 * 扩展事件功能
 */
export class ExtendEvent extends EventTarget {
    /**缓存事件 */
    private _eventList: (string | number)[];

    public constructor() {
        super();
        this._eventList = [];
    }

    public on<F extends (...any: any[]) => void>(type: string, callback: F, thisArg?: any, once?: boolean): F {
        if (!type) {
            return;
        }
        this._eventList.push(type);
        return super.on(type, callback, thisArg, once);
    }

    public once<F extends (...any: any[]) => void>(type: string, callback: F, thisArg?: any): F {
        return this.on(type, callback, thisArg, true);
    }

    /**
     * 清除监听所有事件
     * @param type 事件类型 null则清除注册所有事件
     */
    public offAll(type?: string) {
        if (type != undefined) {
            super.off(type);
        }
        else {
            for (let evt of this._eventList) {
                super.off(evt);
            }
            this._eventList.length = 0;
        }
    }

}