import { _decorator, Component, Node, math, UITransform, Label, HorizontalTextAlignment, Vec3, SpriteFrame, Sprite, ButtonComponent } from 'cc';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
import { Global } from '../../../../../scripts/main/Global';
import { ScreenType } from '../../../../../scripts/framework/ui/UIView';
;
const { ccclass, property } = _decorator;

/**
 * UIButton横竖屏设置组件
 */
@ccclass('UIButtonScreenSwitch')
export class UIButtonScreenSwitch extends Component {

    @property(SpriteFrame)
    private horNormalSpr: SpriteFrame;
    @property(SpriteFrame)
    private horPressedSpr: SpriteFrame;
    @property(SpriteFrame)
    private horHoverSpr: SpriteFrame;
    @property(SpriteFrame)
    private horDisabledSpr: SpriteFrame;

    @property(SpriteFrame)
    private verNormalSpr: SpriteFrame;
    @property(SpriteFrame)
    private verPressedSpr: SpriteFrame;
    @property(SpriteFrame)
    private verHoverSpr: SpriteFrame;
    @property(SpriteFrame)
    private verDisabledSpr: SpriteFrame;

    start() {
        this.addListener();
        this.onScreenSwitch();
    }

    public onDestroy() {
        this.removeListener();
    }

    private onScreenSwitch(): void {
        let btn = this.node.getComponent(ButtonComponent)
        if (btn) {
            if (Global.gameScreenType == ScreenType.Landscape) {
                btn.normalSprite = this.horNormalSpr
                btn.pressedSprite = this.horPressedSpr
                btn.hoverSprite = this.horHoverSpr
                btn.disabledSprite = this.horDisabledSpr
            } else {
                btn.normalSprite = this.verNormalSpr
                btn.pressedSprite = this.verPressedSpr
                btn.hoverSprite = this.verHoverSpr
                btn.disabledSprite = this.verDisabledSpr
            }
        }
    }

    private addListener(): void {
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    private removeListener(): void {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }
}

