import { _decorator, Component, Label, Node, NodeEventType } from 'cc';
import { ScreenType, UIView } from '../../../../scripts/framework/ui/UIView';
import { UIButton } from '../../../../scripts/framework/ui/basic_ui/UIButton';
import { Global } from '../../../../scripts/main/Global';
import { Eventer } from '../../../../scripts/framework/Eventer';
import { GameEventType } from '../../../gamesCommon/script/GameEventType';
import i18n from '../../../../scripts/framework/language/i18n';
const { ccclass, property } = _decorator;

@ccclass('RollQuickSpinView')
export class RollQuickSpinView extends UIView {

    @property(Node)
    node_cont: Node;

    @property(Label)
    lab_title: Label;

    @property(Node)
    node_back: Node;

    @property(Label)
    lab_txt: Label;

    @property(Label)
    lab_check: Label;

    @property(UIButton)
    btn_close: UIButton;

    @property(Node)
    btn_check: Node;
    @property(Node)
    node_check: Node;

    @property(UIButton)
    btn_confirm: UIButton;
    @property(Label)
    lab_confirm: Label;

    /** 计时器 */
    private _timeout: number = 0;
    /** 时长 */
    private _delay: number = 2000;

    start() {
        this.refreshCheck();
    }

    public onOpen(): void {
        this.onEvent();
        this.screesSwitch();

        this.lab_txt.string = i18n.tr(1003007);
        this.lab_confirm.string = i18n.tr(1003008);
        this.lab_check.string = this.lab_title.string = i18n.tr(3001001);
    }

    public onClose() {
        this.offEvent();

        if (this._timeout) {
            clearTimeout(this._timeout);
            this._timeout = 0;
        }
    }

    protected refreshCheck() {
        this.node_check.active = Global.quickSpin;
    }

    update(deltaTime: number) {
    }

    private onConfirmTouch() {
        Global.quickSpin = this.node_check.active;
        Eventer.getInstance().emit(GameEventType.OnRollQuickSpinConfirm);
        this.close();
    }

    private onCloseTouch() {
        this.close();
    }

    private onCheckTouch() {
        this.node_check.active = !this.node_check.active;
    }

    /** 横竖屏切换 */
    private screesSwitch() {
        if (Global.gameScreenType == ScreenType.Landscape) {
            this.node.angle = 0;
        } else {
            this.node.angle = 90;
        }
    }

    private onEvent() {
        this.btn_close.touchEndedFun = this.onCloseTouch.bind(this);
        this.btn_confirm.touchEndedFun = this.onConfirmTouch.bind(this);
        this.btn_check.on(NodeEventType.TOUCH_END, this.onCheckTouch, this);
        this._timeout = setTimeout(() => {
            this.node_back.on(NodeEventType.TOUCH_END, this.onCloseTouch, this);
        }, this._delay)
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.screesSwitch, this);
        Eventer.getInstance().on(GameEventType.RollQuickSpinClose, this.onCloseTouch, this);
    }

    private offEvent() {
        this.btn_check.off(NodeEventType.TOUCH_END, this.onCheckTouch, this);
        this.node_back.off(NodeEventType.TOUCH_END, this.onCloseTouch, this);
        this.btn_close.touchEndedFun = null;
        this.btn_confirm.touchEndedFun = null;
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        Eventer.getInstance().offName(GameEventType.RollQuickSpinClose, this);
    }
} 