import { _decorator, Component, Label, Node, tween, Vec3 } from 'cc';
import { Eventer } from '../../../../scripts/framework/Eventer';
import { GameEventType } from '../../../gamesCommon/script/GameEventType';
import { Global } from '../../../../scripts/main/Global';
import { ScreenType } from '../../../../scripts/framework/ui/UIView';
import { UIButton } from '../../../../scripts/framework/ui/basic_ui/UIButton';
import { GameCommonModel } from '../../../gamesCommon/script/GameCommonModel';
import { RollCommonModel } from '../RollCommonModel';
import GamesData from '../../../gamesCommon/script/GamesData';
import GameResPath from '../../../gamesCommon/script/constDatas/GameResPath';
import i18n from '../../../../scripts/framework/language/i18n';
import { GameComUtils } from '../../../gamesCommon/script/utils/GameComUtils';
const { ccclass, property } = _decorator;

@ccclass('RollBetView')
export class RollBetView extends Component {

    @property(Label)
    public lab_title: Label;

    @property(UIButton)
    public dec_bet_btn: UIButton;
    @property(UIButton)
    public add_bet_btn: UIButton;
    @property(Label)
    public lab_bet_title: Label;
    @property(Label)
    public lab_bet: Label;

    @property(UIButton)
    public dec_value_btn: UIButton;
    @property(UIButton)
    public add_value_btn: UIButton;
    @property(Label)
    public lab_value_title: Label;
    @property(Label)
    public lab_value: Label;

    @property(UIButton)
    public dec_total_bet_btn: UIButton;
    @property(UIButton)
    public add_total_bet_btn: UIButton;
    @property(Label)
    public lab_total_title: Label;
    @property(Label)
    public lab_total_bet: Label;

    @property(UIButton)
    public max_bet_btn: UIButton;

    /**0:bet 1:value 2 total */
    private _sectionArray: number[][] = [];

    start() {
        //this.init();
    }

    public init(): void {
        if (GameCommonModel.getInstance().valueGameId.indexOf(Global.gameId) != -1) {
            this._sectionArray = [];
            this._addEvents();
            this._onScreenSwitch();
        }
        this.node.active = false;
    }

    private _addEvents() {
        this.add_value_btn.touchEndedFun = this.onBetClick.bind(this);
        this.dec_value_btn.touchEndedFun = this.onBetClick.bind(this);
        this.add_bet_btn.touchEndedFun = this.onValueClick.bind(this);
        this.dec_bet_btn.touchEndedFun = this.onValueClick.bind(this);
        this.add_total_bet_btn.touchEndedFun = this.onTotalBetClick.bind(this);
        this.dec_total_bet_btn.touchEndedFun = this.onTotalBetClick.bind(this);
        this.max_bet_btn.touchEndedFun = this.onMaxClick.bind(this);

        this.add_value_btn.touchBeganFun = this.onBeganClickBtn.bind(this);
        this.dec_value_btn.touchBeganFun = this.onBeganClickBtn.bind(this);
        this.add_bet_btn.touchBeganFun = this.onBeganClickBtn.bind(this);
        this.dec_bet_btn.touchBeganFun = this.onBeganClickBtn.bind(this);
        this.add_total_bet_btn.touchBeganFun = this.onBeganClickBtn.bind(this);
        this.dec_total_bet_btn.touchBeganFun = this.onBeganClickBtn.bind(this);
        this.max_bet_btn.touchBeganFun = this.onBeganClickBtn.bind(this);

        this.add_value_btn.touchCancelFun = this.onCancelClickBtn.bind(this);
        this.dec_value_btn.touchCancelFun = this.onCancelClickBtn.bind(this);
        this.add_bet_btn.touchCancelFun = this.onCancelClickBtn.bind(this);
        this.dec_bet_btn.touchCancelFun = this.onCancelClickBtn.bind(this);
        this.add_total_bet_btn.touchCancelFun = this.onCancelClickBtn.bind(this);
        this.dec_total_bet_btn.touchCancelFun = this.onCancelClickBtn.bind(this);
        this.max_bet_btn.touchCancelFun = this.onCancelClickBtn.bind(this);

        Eventer.getInstance().on(GameEventType.ScreenSwitch, this._onScreenSwitch, this);
        Eventer.getInstance().on(GameEventType.RollUpdateBet, this._updateBet, this);
        Eventer.getInstance().on(GameEventType.OnReceiveSlotInfo, this.initInfo, this);
        Eventer.getInstance().on(GameEventType.RollChageBet, this.totalBetClickEven, this);
    }

    private onBeganClickBtn(target: UIButton) {
        target.node.setScale(0.9, 0.9, 0.9);
    }

    private onCancelClickBtn(target: UIButton) {
        target.node.setScale(1, 1, 1);
    }



    private initInfo() {

    }

    private onBetClick(target: UIButton) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.betList || gameComModel.betList.length <= 0) {
            return;
        }
        GameResPath.playRollCommonSound("click_1");
        this.onCancelClickBtn(target);
        let curBetIndex = GameCommonModel.getInstance().curBetIndex;
        let nextIndex: number;
        if (target == this.add_value_btn) {
            nextIndex = curBetIndex + 1;
        }
        else if (target == this.dec_value_btn) {
            nextIndex = curBetIndex - 1;
        }

        let betCount = gameComModel.betList.length;
        if (nextIndex <= 0) {
            nextIndex = 0;
        }
        if (nextIndex >= betCount - 1) {
            nextIndex = betCount - 1;
        }
        gameComModel.curBetIndex = nextIndex;
        this.setBetBtnState(nextIndex);
        this.updateValue();
        Eventer.getInstance().emit(GameEventType.RollUpdateBet);
        Eventer.getInstance().emit(GameEventType.RollCloseAutoPlayMenu);

    }

    private setTionArr(): void {
        let gameComModel = GameCommonModel.getInstance();
        let rollCommonModel = RollCommonModel.getInstance();
        if (gameComModel.betList && gameComModel.betList.length) {
            this._sectionArray = [];
            let line = rollCommonModel.curBetLine;
            let rate = rollCommonModel.betRate;
            for (let i = 0; i < gameComModel.betList.length; i++) {
                let bet = gameComModel.betList[i];
                for (let j = 0; j < gameComModel.valueList.length; j++) {
                    let arr = [];
                    let valueIndex = gameComModel.valueList[j];
                    let totalNum = bet * valueIndex * line * rate;
                    arr.push(i, j, totalNum);
                    this._sectionArray.push(arr);
                }
            }

            for (let i = 0; i < this._sectionArray.length - 1; i++) {
                for (let j = i; j < this._sectionArray.length - 1; j++) {
                    if (this._sectionArray[i][2] > this._sectionArray[j][2]) {
                        let temp = this._sectionArray[i];
                        this._sectionArray[i] = this._sectionArray[j];
                        this._sectionArray[j] = temp;
                    }
                }
            }
        }
    }

    private initLab() {
        let line = RollCommonModel.getInstance().curBetLine;
        this.lab_title.string = i18n.tr(1005001, [line]);
        this.lab_bet_title.string = i18n.tr(1005002);
        this.lab_value_title.string = i18n.tr(1005003);
        this.lab_total_title.string = i18n.tr(1005004);
    }

    public totalBetClickEven(msg) {
        Eventer.getInstance().emit(GameEventType.RollCloseAutoPlayMenu);
        if (msg[0]) {
            this.onTotalBetClick(this.add_total_bet_btn, msg[1]);
        } else {
            this.onTotalBetClick(this.dec_total_bet_btn, msg[1]);
        }
    }

    private onTotalBetClick(target: UIButton, totalBetNum) {
        if (this._sectionArray.length) {
            let value = GameCommonModel.getInstance().curValue;
            let bet = GameCommonModel.getInstance().curBet;
            let line = RollCommonModel.getInstance().curBetLine;
            let rate = RollCommonModel.getInstance().betRate;
            let totalBet = value * bet * line * rate;
            this.onCancelClickBtn(target);
            if (totalBetNum) {
                totalBet = totalBetNum;
            }
            let section;
            if (target == this.add_total_bet_btn) {
                let isChange = false;
                for (let i = 0; i < this._sectionArray.length; i++) {
                    if (this._sectionArray[i][2] > totalBet) {
                        section = this._sectionArray[i];
                        isChange = true;
                        break;
                    }
                }
                if (!isChange) {
                    let len = this._sectionArray.length - 1;
                    if (this._sectionArray[len][2] == totalBet) {
                        section = this._sectionArray[0];
                    }
                }

            } else if (target == this.dec_total_bet_btn) {
                let isChange = false;
                for (let i = this._sectionArray.length - 1; i >= 0; i--) {
                    if (this._sectionArray[i][2] < totalBet) {
                        section = this._sectionArray[i];
                        isChange = true;
                        break;
                    }
                }
                if (!isChange) {
                    let len = this._sectionArray.length - 1;
                    if (this._sectionArray[0][2] == totalBet) {
                        section = this._sectionArray[len];
                    }
                }
            }
            GameCommonModel.getInstance().curBetIndex = section[0];
            GameCommonModel.getInstance().curValueIndex = section[1];
            this.updateValue();
        }

    }

    private onValueClick(target: UIButton) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.valueList || gameComModel.valueList.length <= 0) {
            return;
        }
        this.onCancelClickBtn(target);
        let curValue = gameComModel.curValueIndex;
        let nextIndex: number;
        if (target == this.add_bet_btn) {
            nextIndex = curValue + 1;
        }
        else if (target == this.dec_bet_btn) {
            nextIndex = curValue - 1;
        }
        let betCount = gameComModel.valueList.length;
        if (nextIndex <= 0) {
            nextIndex = 0;
        }
        if (nextIndex >= betCount - 1) {
            nextIndex = betCount - 1;
        }
        gameComModel.curValueIndex = nextIndex;
        this.setValueBtnState(nextIndex);
        this.updateValue();
        GameResPath.playRollCommonSound("click_1");
        Eventer.getInstance().emit(GameEventType.RollUpdateBet);
        Eventer.getInstance().emit(GameEventType.RollCloseAutoPlayMenu);
    }

    /**设置按钮状态 */
    private _setBtnState() {
        if (this._sectionArray.length) {
            let value = GameCommonModel.getInstance().curValue;
            let bet = GameCommonModel.getInstance().curBet;
            let line = RollCommonModel.getInstance().curBetLine;
            let rate = RollCommonModel.getInstance().betRate;
            let curBetIndex = GameCommonModel.getInstance().curBetIndex;
            let curValueIndex = GameCommonModel.getInstance().curValueIndex;
            let totalBet = value * bet * line * rate;
            let section = [];
            let len = []
            for (let i = 0; i < this._sectionArray.length; i++) {
                if (this._sectionArray[i][2] == totalBet) {
                    section.push(this._sectionArray[i]);
                    len.push(i);
                }
            }
            for (let i = 0; i < section.length; i++) {
                if (section[i][0] == curBetIndex || section[i][1] == curValueIndex) {
                    this.setBetBtnState(section[i][0]);
                    this.setValueBtnState(section[i][1]);
                    this.setTotalBtnState(len[i]);
                    break;
                }

            }
        }
    }

    /**
    * 设置押注索引
    * @param betIndex 索引
    */
    public setBetBtnState(betIndex: number) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.betList || gameComModel.betList.length <= 0) {
            return;
        }
        this.add_value_btn.interactable = true;
        this.dec_value_btn.interactable = true;
        let betCount = gameComModel.betList.length;
        if (betIndex <= 0) {
            this.add_value_btn.interactable = true;
            this.dec_value_btn.interactable = false;
        }
        if (betIndex >= betCount - 1) {
            this.add_value_btn.interactable = false;
            this.dec_value_btn.interactable = true;
        }
        this.add_value_btn.setColor(this.add_value_btn.interactable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor);
        this.dec_value_btn.setColor(this.dec_value_btn.interactable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor);
    }

    /**
   * 设置押注索引
   * @param valueIndex 索引
   */
    public setValueBtnState(valueIndex: number) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.valueList || gameComModel.valueList.length <= 0) {
            return;
        }
        this.add_bet_btn.interactable = true;
        this.dec_bet_btn.interactable = true;
        let betCount = gameComModel.valueList.length;
        if (valueIndex <= 0) {
            this.add_bet_btn.interactable = true;
            this.dec_bet_btn.interactable = false;
        }
        if (valueIndex >= betCount - 1) {
            this.add_bet_btn.interactable = false;
            this.dec_bet_btn.interactable = true;
        }
        this.add_bet_btn.setColor(this.add_bet_btn.interactable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor);
        this.dec_bet_btn.setColor(this.dec_bet_btn.interactable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor);
    }

    /**
  * 设置总押注索引
  * @param totalIndex 索引
  */
    public setTotalBtnState(totalIndex: number) {
        if (this._sectionArray.length) {
            this.add_total_bet_btn.interactable = true;
            this.dec_total_bet_btn.interactable = true;
            let totalBetcount = this._sectionArray.length;
            if (totalIndex <= 0) {
                this.add_total_bet_btn.interactable = true;
                this.dec_total_bet_btn.interactable = false;
            }
            if (totalIndex >= totalBetcount - 1) {
                this.add_total_bet_btn.interactable = false;
                this.dec_total_bet_btn.interactable = true;

            }
            this.add_total_bet_btn.setColor(this.add_total_bet_btn.interactable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor);
            this.dec_total_bet_btn.setColor(this.dec_total_bet_btn.interactable ? GameComUtils.btnEffColor : GameComUtils.btnFailsColor);
        }
    }

    private _updateBet() {
        let value = GameCommonModel.getInstance().curValue;
        let bet = GameCommonModel.getInstance().curBet;
        let line = RollCommonModel.getInstance().curBetLine;
        let rate = RollCommonModel.getInstance().betRate;
        let total = value * bet * line * rate;
        this.lab_bet.string = value.toString();
        this.lab_value.string = Global.currencyName + GamesData.formatScore(bet, false);;
        this.lab_total_bet.string = Global.currencyName + GamesData.formatScore(total, false);
        this.setTionArr();
        this.initLab();
    }

    public updateValue() {
        this._updateBet();
        this._setBtnState();
        let addBtnInteractable = this.add_total_bet_btn.interactable;
        let decBtnInteractable = this.dec_total_bet_btn.interactable;
        Eventer.getInstance().emit(GameEventType.RollUiewpdateBetView, [decBtnInteractable, addBtnInteractable]);
    }



    private onMaxClick() {
        if (this._sectionArray.length) {
            this.onCancelClickBtn(this.max_bet_btn);
            let len = this._sectionArray.length - 1;
            GameCommonModel.getInstance().curBetIndex = this._sectionArray[len][0];
            GameCommonModel.getInstance().curValueIndex = this._sectionArray[len][1];
            this.updateValue();
        }

    }

    private _onScreenSwitch() {
        if (Global.gameScreenType == ScreenType.Landscape) {

        } else {

        }
    }

    public offEvent() {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        Eventer.getInstance().offName(GameEventType.RollUpdateBet, this);
        Eventer.getInstance().offName(GameEventType.OnReceiveSlotInfo, this);
        Eventer.getInstance().offName(GameEventType.RollChageBet, this);

    }

    onDisable() {
        // Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        // Eventer.getInstance().offName(GameEventType.RollUpdateBet, this);
        // Eventer.getInstance().offName(GameEventType.OnReceiveSlotInfo, this);

    }

}


