import { _decorator, RichText, Sprite, SpriteFrame } from 'cc';
import { RollBottomWinLineBaseComp } from './RollBottomWinLineBaseComp';
import { RollBottomWinLineVo } from '../RollBottom';
import { ResManager } from '../../../../../scripts/framework/manager/ResManager';
import GamesData from '../../../../gamesCommon/script/GamesData';
import { Global } from '../../../../../scripts/main/Global';
import i18n from '../../../../../scripts/framework/language/i18n';
const { ccclass, property } = _decorator;

@ccclass('RollBottomWinLineComp4')
export class RollBottomWinLineComp4 extends RollBottomWinLineBaseComp {

    /** 赢分节点 */
    @property(RichText)
    paysLab: RichText;

    /** icon */
    @property(Sprite)
    iconImg: Sprite;

    start() {

    }


    /**
     * 设置数据
     * @param data 
     */
    public setData(data: RollBottomWinLineVo) {
        let iconRes = data.iconRes;
        let iconWin = data.iconWin;

        if (iconRes instanceof SpriteFrame) {
            this.setSpriteFrame(this.iconImg.node, iconRes);
        } else {
            ResManager.Instance().load(GamesData.gameId.toString(), iconRes as string, SpriteFrame, () => { }, (evt: any) => {
                let spriteFrame: SpriteFrame = evt.data;
                this.setSpriteFrame(this.iconImg.node, spriteFrame);
            });
        }

        let formula = `${Global.currencyName}${GamesData.formatMoney(iconWin)}`
        this.paysLab.string = i18n.tr(3002006, formula);
    }

}

