    protected onStart(target: UIButton) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.betList || gameComModel.betList.length <= 0) {
            return;
        }
        GameComUtils.c2sStat(StatConst.SLOT_TIMES);

        if (!this.model.isOpenAuto)
            if (this.model.isOpenAutoMenu && this.model.selAutoPlayIdx >= 0) {
                this.model.isOpenAuto = true;
                //【622】开启自动，默认开启快速
                if (!Global.quickSpin)
                    this.dealWithQuick();
                let list = this.model.autoPlayTimesList;
                let idx = this.model.selAutoPlayIdx;
                this.model.autoPlayTime = list[idx];
                GameComUtils.c2sStat(StatConst.START_AUTO_PLAY, list[idx]);
                this.showSpinTime();
            }

        GameResPath.playRollCommonSound("click_1");
        Eventer.getInstance().emit(GameEventType.RollStart);
        Eventer.getInstance().emit(GameEventType.RollCloseAutoPlayMenu);
        Eventer.getInstance().emit(GameEventType.SpinBtnSwitch);
    }

