    protected onBetClick(target: UIButton) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.betList || gameComModel.betList.length <= 0) {
            return;
        }
        let value = gameComModel.curValue;
        let bet = gameComModel.curBet;
        let line = RollCommonModel.getInstance().curBetLine + RollCommonModel.getInstance().doubleLine
        let rate = RollCommonModel.getInstance().betRate;
        let totalBet = value * bet * line * rate;
        GameResPath.playRollCommonSound("click_1");
    
        const isValueGame = gameComModel.valueGameId.indexOf(Global.gameId) != -1;
        const isValueAGame = gameComModel.valueAGameId.indexOf(Global.gameId) != -1;
    
        if (isValueGame || isValueAGame) {
            const isIncrease = target == this.btn_bet_add;
            Eventer.getInstance().emit(GameEventType.RollChageBet, [isIncrease, totalBet, isValueAGame ? target : undefined]);
            
            if (isValueGame && (!this.rollBetView.node.active || !this.other_btm.rollBetView.node.active)) {
                this.rollBetView.node.active = this.other_btm.rollBetView.node.active = true;
            }
            
            if (isValueAGame) {
                Eventer.getInstance().emit(GameEventType.RollCloseAutoPlayMenu);
            }
    
            this.setBtnNormal(target.node);
            return;
        }
    
        // Original logic for other game types
        let curBetIndex = gameComModel.curBetIndex;
        let nextIndex = target == this.btn_bet_add || target == this.other_btm.btn_bet_add ? curBetIndex + 1 : curBetIndex - 1;
    
        this.setBetIndex(nextIndex);
        Eventer.getInstance().emit(GameEventType.RollChageBet);
        Eventer.getInstance().emit(GameEventType.RollCloseAutoPlayMenu);
        this.setBtnNormal(target.node);
    }
    
