    /**
     * 设置押注索引
     * @param betIndex 索引
     */
    public setBetIndex(betIndex: number) {
        let gameComModel = GameCommonModel.getInstance();
        if (!gameComModel.betList || gameComModel.betList.length <= 0) {
            return;
        }
        let betCount = gameComModel.betList.length;
        if (betIndex < 0) {
            betIndex = betCount - 1;
        }
        if (betIndex >= betCount) {
            betIndex = 0;
        }
        gameComModel.curBetIndex = betIndex;
        this.updateBet();
    }

    public updateBet() {
        let curBet = GameCommonModel.getInstance().curBet;
        let line = this.model.curBetLine + this.model.doubleLine
        let value = GameCommonModel.getInstance().curValue;
        let bet = this.model.totalBet
        if (GameCommonModel.getInstance().valueGameId.indexOf(Global.gameId) != -1) {
            bet = curBet * line * this.model.betRate * value;
        }
        if (GameCommonModel.getInstance().valueAGameId.indexOf(Global.gameId) != -1) {
            bet = curBet * line * this.model.betRate * value;
        }
        let score = GamesData.formatScore(bet, false);
        this.lab_bet.string = this.betStr(score);
        this.other_btm.lab_bet.string = this.betStr(score);
        Eventer.getInstance().emit(GameEventType.RollUpdateBet, bet);
    }

