    /**
     * 赢钱数增加到win
     * @param win 服务端分数
     * @param delay 时长 ms
     */
    public addToWinMoney(win: number, delay: number = 1000) {
        //音效
        if (win > 0 && this.lab_win.getEndValue() != win && this.node_win.active) {
            if (!this._winRollSound?.clip?.onLoaded)
                this.other_btm.winRollStart();
            else
                this.winRollStart();
        }
        //赢分上限
        win = this.checkMaxWinMoney(win);
        //赢分无需滚动判断
        if (this._noWinRoll || Global.quickSpin) {
            this._noWinRoll = false;
            this.lab_win.setValue(win);
            this.other_btm.lab_win.setValue(win);
        } else {
            this.lab_win.addValueTo(win, true, delay);
            this.other_btm.lab_win.addValueTo(win, true, delay);
        }
    }

    /**
     * 赢钱数增加值
     * @param add 增量值 服务端分数
     * @param delay 时长 ms
     */
    public addWinMoney(add: number, delay: number = 1000) {
        //音效
        if (add > 0 && this.node_win.active)
            if (!this._winRollSound?.clip?.onLoaded)
                this.other_btm.winRollStart();
            else
                this.winRollStart();

        let lastWin = this.lab_win.getEndValue()
        let allWin = add + lastWin
        allWin = this.checkMaxWinMoney(allWin)
        add = allWin - lastWin
        //赢分无需滚动判断
        if (this._noWinRoll || Global.quickSpin) {
            this._noWinRoll = false;
            let endValue = allWin;
            this.lab_win.setValue(endValue);
            this.other_btm.lab_win.setValue(endValue);
        } else {
            this.lab_win.addValue(add, true, delay);
            this.other_btm.lab_win.addValue(add, true, delay);
        }
    }

