    /** 展示赢线 */
    showWinningLine(data: RollBottomWinLineVo): void {
        switch (data.type) {
            case ROLL_BOTTOM_WIN_LINE_TYPE.NONE: {
                //Log.d('win line type none');
                this.showNodeWin();
                this.other_btm.showNodeWin();
                break;
            }
            case ROLL_BOTTOM_WIN_LINE_TYPE.TOTAL: {
                //Log.d('win line type total', data);
                this.showTotalWin(data.totalWin);
                this.other_btm.showTotalWin(data.totalWin);

                //音效
                if (this.lab_win.isRolling && this.node.parent.active)
                    this.winRollStart();
                break;
            }
            default:
                //Log.d('win line type 1', data);
                this.showLineWin(data);
                this.other_btm.showLineWin(data);

                //音效
                if (this.lab_win.isRolling && this.node.parent.active)
                    this.winRollStart();
                break;
        }
    }

