    private startBtnRollHandler() {
        if (!this.btn_start.interactable) return;
        this.stopStartRoll();
        this.btn_start.node.angle = 180;
        tween(this.btn_start.node)
            .to(0.4, { angle: 140 }, { easing: 'quartInOut' })
            .to(0.2, { angle: 190 }, { easing: 'quartInOut' })
            .to(0.1, { angle: 180 }, { easing: 'sineOut' })
            .to(0.1, { angle: 190 }, { easing: 'sineOut' })
            .to(0.1, { angle: 180 }, { easing: 'sineOut' })
            .start()
    }

    private playStartRoll() {
        this._spinBtnRolling = true;
        this.btn_start.node.angle = 180;
        this.btn_start.interactable = false;
        this.btn_start.node.active = true;
        this.btn_stop.node.active = false;
        this.other_btm.btn_start.interactable = false;
        this.other_btm.btn_start.node.active = true;
        this.other_btm.btn_stop.node.active = false;
        this.stopStartRoll();

        tween(this.btn_start.node)
            .to(0.1, { angle: 190 }, { easing: 'sineOut' })
            .to(0.2, { angle: -180 }, { easing: 'sineOut' })
            .call(() => {
                this.btn_start.node.angle = 180;
            })
            .start()

        tween(this.other_btm.btn_start.node)
            .to(0.1, { angle: 190 }, { easing: 'sineOut' })
            .to(0.2, { angle: -180 }, { easing: 'sineOut' })
            .call(() => {
                this.btn_start.interactable = true;
                this.other_btm.btn_start.interactable = true;
                this.other_btm.btn_start.node.angle = 180;
                this._spinBtnRolling = false;
                this.setStartBtn();
            })
            .start()
    }

    private stopStartRoll() {
        Tween.stopAllByTarget(this.btn_start.node);
        Tween.stopAllByTarget(this.other_btm.btn_start.node);
    }

