import { _decorator, Asset, AssetManager, assetManager } from 'cc';
import { EGAME_TYPE } from '../../../scripts/common/define/EnumDefine';
import { Entry } from '../../../scripts/framework/hall/entry/Entry';
import { EntryManager } from '../../../scripts/framework/hall/entry/EntryManager';
import { BundleManager } from '../../../scripts/framework/manager/BundleManager';
import { Global } from '../../../scripts/main/Global';
import GamesData from '../../gamesCommon/script/GamesData';
import { BUNDLE_NAME } from '../../gamesCommon/script/UIGameDefined';
import { RollCommonManager } from './RollCommonManager';
const { ccclass } = _decorator;

@ccclass('RollCommonEntry')
export class RollCommonEntry extends Entry {

    static bundle = BUNDLE_NAME.rollCommon;

    constructor() {
        super();
    }

    protected initData(): void {
    }

    protected loadResources(completeCb: () => void): void {
        let bundleName: string = RollCommonEntry.bundle;
        if (GamesData.loadingRecord.hasOwnProperty(bundleName)) {
            return;
        }

        GamesData.loadingRecord[bundleName] = EGAME_TYPE.PUB_RES;

        let bundle: AssetManager.Bundle = BundleManager.getInstance().getBundle(bundleName);
        bundle.loadDir('resources', (err: Error | null, data: any) => {

            delete GamesData.loadingRecord[bundleName];

            let gameType: EGAME_TYPE = Global.gameType;
            if (gameType != EGAME_TYPE.SLOTS) {
                GamesData.removeCommonBundle();
                return;
            }

            if (!err) {
                completeCb();
                this.onComplete();
            }
        })
    }

    protected onProgress(current: number, total: number): void {
    }

    protected openGameView(): void {
        RollCommonManager.getInstance().registerMsgListener();

        EntryManager.getInstance().enterBundle(Global.gameId + "");
    }

    protected onComplete(): void {
        Log.d("加载 rollCommon 资源完毕。。。");
        RollCommonManager.getInstance().loadPlayback();
        RollCommonManager.getInstance().c2sEntranceInfo(GamesData.gameId);
    }

    protected closeGameView(): void {
        RollCommonManager.getInstance().clean();
        RollCommonManager.clearInstance();
    }
}
EntryManager.getInstance().register(RollCommonEntry);

