import { _decorator, Component, Sprite, SpriteFrame } from 'cc';
import { Eventer } from '../../../../scripts/framework/Eventer';
import { CacheManager } from '../../../../scripts/framework/manager/CacheManager';
import { ResManager } from '../../../../scripts/framework/manager/ResManager';
import { GameCommonModel } from '../../../gamesCommon/script/GameCommonModel';
import { GameEventType } from '../../../gamesCommon/script/GameEventType';
import GamesData from '../../../gamesCommon/script/GamesData';
import { BUNDLE_NAME } from '../../../gamesCommon/script/UIGameDefined';
import { RollCommonManager } from '../RollCommonManager';
import { JackPotType, RollCommonModel } from '../RollCommonModel';
import { RollValue } from './RollValue';
const { ccclass, property } = _decorator;

@ccclass('JackPotComponent')
export class JackPotComponent extends Component {

    @property(RollValue)
    private lab_random: RollValue;
    @property(RollValue)
    private lab_major: RollValue;
    @property(RollValue)
    private lab_minor: RollValue;

    @property(Sprite)
    private tag_lang_random: Sprite;
    @property(Sprite)
    private tag_lang_major: Sprite;
    @property(Sprite)
    private tag_lang_minor: Sprite;

    /**major彩金最大最小值 */
    private _majorMinMax: number[];
    private _isChangeMajor = false;

    /**minor彩金最大最小值 */
    private _minorMinMax: number[];
    private _isChangeMinor = false;

    private _lastChange = 0;
    private _changeDelay = 1000;

    private _isFirstGet = true;
    private _isChangeRandom = false;
    private _lastRandomGet = 0;
    private _randomDelay = 10000;
    private _model: RollCommonModel;

    protected __preload(): void {
        this._model = RollCommonModel.getInstance();
        this._init();
    }
    // protected onLoad(): void{
    // start() {

    onDestroy(): void {
        this._removeEvent();
    }

    protected _init() {

        if (this.lab_random) {
            this.lab_random.init(false, 163);
        }
        if (this.lab_major) {
            this.lab_major.init(false, 163);
        }
        if (this.lab_minor) {
            this.lab_minor.init(false, 163);
        }

        this._changeLanguage();

        this._addEvent();
        RollCommonManager.getInstance().c2sGetMajMin();
        RollCommonManager.getInstance().c2sGetBonus("random");
    }

    private socketOpenCallBack(evt): void {
        RollCommonManager.getInstance().c2sGetMajMin();
        RollCommonManager.getInstance().c2sGetBonus("random");
    }

    private _changeLanguage() {

        let mLanguage: string = GamesData.getGameLanguageStr();

        let path = `resources/texture/rollCommonRec/rollCommonAtlas/MAJOR_${mLanguage}/spriteFrame`;
        if (this.tag_lang_major) {
            ResManager.Instance().load(BUNDLE_NAME.rollCommon, path, SpriteFrame, () => { }, (evt: any) => { this.tag_lang_major.spriteFrame = evt.data; });
        }

        if (this.tag_lang_random) {
            path = `resources/texture/rollCommonRec/rollCommonAtlas/Random_${mLanguage}/spriteFrame`;
            ResManager.Instance().load(BUNDLE_NAME.rollCommon, path, SpriteFrame, () => { }, (evt: any) => { this.tag_lang_random.spriteFrame = evt.data; });
        }

        if (this.tag_lang_minor) {
            path = `resources/texture/rollCommonRec/rollCommonAtlas/Minor_${mLanguage}/spriteFrame`;
            ResManager.Instance().load(BUNDLE_NAME.rollCommon, path, SpriteFrame, () => { }, (evt: any) => { this.tag_lang_minor.spriteFrame = evt.data; });
        }
    }

    update(deltaTime: number) {
        if (this._lastChange + this._changeDelay < GameCommonModel.getInstance().serverTime) {
            this._lastChange = GameCommonModel.getInstance().serverTime;
            if (this._isChangeMajor) {
                this._showMajor();
            }
            if (this._isChangeMinor) {
                this._showMinor();
            }
        }

        if (this._lastRandomGet + this._randomDelay < GameCommonModel.getInstance().serverTime) {
            this._lastRandomGet = GameCommonModel.getInstance().serverTime;
            if (this._isChangeRandom) {
                //-> 发送消息
                RollCommonManager.getInstance().c2sGetBonus(JackPotType.RANDOM);
            }
        }
    }

    /**
    * 彩金奖励
    * @param type 奖励类型
    * @param value 奖励数值
    * @returns 
    */
    private _payJackPot(mData: any) {
        let type: string = mData.type;
        let value: number = mData.value;
        if (value <= 0) {
            return;
        }
        let rollValue: RollValue;
        let delay = value;
        switch (type) {
            case JackPotType.RANDOM:
                rollValue = this.lab_random;
                this.stopChangeRandom();
                break;
            case JackPotType.MAJOR:
                rollValue = this.lab_major;
                this.stopChangeMajor();
                break;
            case JackPotType.MINOR:
                rollValue = this.lab_minor;
                this.stopChangeMinor();
                break;
        }
        if (rollValue) {
            rollValue.setValue(value);
            rollValue.addValueTo(0, true, delay);
        }
        if (this._model.mainViewAddMoneyFun) {
            this._model.mainViewAddMoneyFun(value, delay);
        }
    }

    /**设置彩金最大最小值 */
    private _onGetMaxMin(mData: any) {
        // this._majorMinMax = major;
        // this._minorMinMax = minor;
        this._majorMinMax = mData.major;
        this._minorMinMax = mData.minor;
        this.showMajorMinor();
    }

    public showMajorMinor() {
        this._showMajor();
        this._showMinor();
    }

    /**
      * 显示random彩金
      * @param type 彩金类型
      * @param value 彩金值
      */
    private _showRandom(mData: any) {
        let type: string = mData.bonustype;
        let value: number = mData.bonus;
        if (type == JackPotType.RANDOM) {
            if (this._isFirstGet) {
                this.lab_random.setValue(value);
                this._isFirstGet = false;
            }
            else {
                this.lab_random.addValueTo(value, true, 10.2);
            }
            this._isChangeRandom = true;
        }
    }

    /**
     * 显示major彩金
     */
    private _showMajor() {
        let value = GamesData.randomFloat(this._majorMinMax[0], this._majorMinMax[1]);
        this.lab_major.setValue(value);
        this._isChangeMajor = true;
    }

    /**
     * 显示minor彩金
     */
    private _showMinor() {
        let value = GamesData.randomFloat(this._minorMinMax[0], this._minorMinMax[1]);
        this.lab_minor.setValue(value);
        this._isChangeMinor = true;
    }

    public stopChangeRandom() {
        this._isChangeRandom = false;
        this.lab_random.stopRoll();
    }

    public stopChangeMajor() {
        this._isChangeMajor = false;
    }

    public stopChangeMinor() {
        this._isChangeMinor = false;
    }

    protected _addEvent() {
        Eventer.getInstance().on(GameEventType.OnGetJackPotMaxMin, this._onGetMaxMin, this);
        Eventer.getInstance().on(GameEventType.OnGetBonus, this._showRandom, this);
        Eventer.getInstance().on(GameEventType.OnPayBonus, this._payJackPot, this);
        Eventer.getInstance().on(GameEventType.SocketOpen, this.socketOpenCallBack, this);
    }

    protected _removeEvent() {
        Eventer.getInstance().offName(GameEventType.OnGetJackPotMaxMin, this);
        Eventer.getInstance().offName(GameEventType.OnGetBonus, this);
        Eventer.getInstance().offName(GameEventType.OnPayBonus, this);
        Eventer.getInstance().offName(GameEventType.SocketOpen, this);

        let mLanguage: string = GamesData.getGameLanguageStr();

        let path = `resources/texture/rollCommonRec/rollCommonAtlas/MAJOR_${mLanguage}/spriteFrame`;
        if (this.tag_lang_major && this.tag_lang_major.spriteFrame) {
            this.tag_lang_major.spriteFrame.decRef();
            this.tag_lang_major.spriteFrame = null;
        }
        CacheManager.getInstance().remove(BUNDLE_NAME.rollCommon, path);

        path = `resources/texture/rollCommonRec/rollCommonAtlas/Random_${mLanguage}/spriteFrame`;
        if (this.tag_lang_random && this.tag_lang_random.spriteFrame) {
            this.tag_lang_random.spriteFrame.decRef();
            this.tag_lang_random.spriteFrame = null;
        }
        CacheManager.getInstance().remove(BUNDLE_NAME.rollCommon, path);

        path = `resources/texture/rollCommonRec/rollCommonAtlas/Minor_${mLanguage}/spriteFrame`;
        if (this.tag_lang_minor && this.tag_lang_minor.spriteFrame) {
            this.tag_lang_minor.spriteFrame.decRef();
            this.tag_lang_minor.spriteFrame = null;
        }
        CacheManager.getInstance().remove(BUNDLE_NAME.rollCommon, path);
    }

}

